begin;
create temp table checks(name text,passed boolean);
grant insert,select on checks to authenticated;
create function pg_temp.ok(v boolean,n text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',n;end if;insert into checks values(n,true);end$$;
create function pg_temp.reject(p jsonb,vendor boolean,n text) returns void language plpgsql as $$begin begin if vendor then perform public.ig_vendor_portal(p);else perform public.ig_procurement(p);end if;exception when others then insert into checks values(n,true);return;end;raise exception 'FAIL: %',n;end$$;
do $$declare uid uuid;sid uuid;other_uid uuid;claims jsonb;p jsonb;r jsonb;v jsonb;ass jsonb;d jsonb;q jsonb;dashboard jsonb;original_roles text[];original_grants jsonb;due text=((now() at time zone 'Asia/Kolkata')::date+14)::text;
begin
 select u.id,s.id into uid,sid from auth.users u join auth.sessions s on s.user_id=u.id where u.email='akm@indiagully.com' order by s.created_at desc limit 1;
 if sid is null then raise exception 'Owner session required';end if;
 select id into other_uid from auth.users where id<>uid limit 1;
 select roles,practice_grants into original_roles,original_grants from public.ig_profiles where id=uid;
 claims=jsonb_build_object('sub',uid,'session_id',sid,'aal','aal2','role','authenticated');perform set_config('request.jwt.claims',claims::text,true);
 p=jsonb_build_object('action','submit','request_id',gen_random_uuid(),'title','SYSTEM TEST customer requirement','destination','Fictional internal test destination','lines','[{"description":"Test plate","uom":"nos","quantity":24}]'::jsonb);
 update public.ig_profiles set roles=array['client'],practice_grants='{}' where id=uid;
 perform set_config('request.jwt.claims',(claims||'{"aal":"aal1"}')::text,true);
 r=public.ig_procurement(p);
 perform pg_temp.ok(r->>'status'='submitted' and exists(select 1 from public.ig_operations where id=(r->>'rfq_id')::uuid and kind='rfq'),'Customer request creates an RFQ without staff MFA');
 perform pg_temp.ok(public.ig_procurement(p)->>'id'=r->>'id','Retry creates one request and RFQ');
 perform pg_temp.reject(p||'{"title":"Changed request"}',false,'Changed retry payload rejected');
 perform pg_temp.reject(jsonb_build_object('action','quote','id',r->>'id','version',r->'version'),false,'Customer cannot release own quotation');
 perform pg_temp.ok(jsonb_array_length(public.ig_procurement_dashboard())>=1,'Customer sees own request');
 if other_uid is not null then
  update public.ig_procurement_requests set user_id=other_uid where id=(r->>'id')::uuid;
  perform pg_temp.ok(not exists(select 1 from jsonb_array_elements(public.ig_procurement_dashboard()) x where x->>'id'=r->>'id'),'Another customer request is excluded');
  perform pg_temp.reject(jsonb_build_object('action','cancel','id',r->>'id','version',r->'version'),false,'Another customer request cannot be changed');
  update public.ig_procurement_requests set user_id=uid where id=(r->>'id')::uuid;
 end if;
 execute 'set local role authenticated';
 perform pg_temp.ok((select count(*) from public.ig_operations)=0,'Customer cannot read supplier costs or internal operations');
 perform pg_temp.ok((select count(*) from public.ig_vendor_contacts)=0,'Customer cannot enumerate supplier contacts');
 execute 'reset role';
 update public.ig_profiles set roles=original_roles,practice_grants=original_grants where id=uid;perform set_config('request.jwt.claims',claims::text,true);
 v=public.ig_ops_save(jsonb_build_object('request_id',gen_random_uuid(),'kind','vendor','practice','horeca','title','SYSTEM TEST portal vendor','status','active','data','{"company":"Fixture supplier"}'::jsonb));
 perform public.ig_vendor_portal(jsonb_build_object('action','contact','vendor_id',v->>'id','email','akm@indiagully.com'));
 ass=public.ig_vendor_portal(jsonb_build_object('action','assign','vendor_id',v->>'id','rfq_id',r->>'rfq_id','expires_at',now()+interval '2 days'));
 update public.ig_profiles set roles=array['client'],practice_grants='{}' where id=uid;perform set_config('request.jwt.claims',(claims||'{"aal":"aal1"}')::text,true);
 dashboard=public.ig_vendor_portal('{"action":"dashboard"}');
 perform pg_temp.ok(jsonb_array_length(dashboard)=1 and dashboard->0->>'id'=ass->>'id','Enabled verified supplier sees only assigned RFQ');
 perform pg_temp.ok(not (dashboard->0->'rfq'->'lines'->0) ? 'unit_rate','Supplier receives no internal RFQ rate');
 d=jsonb_build_object('reference','TEST-SUPPLIER','valid_until',due,'freight',10,'discount',0,'terms','Test terms only, not a real offer','lines','[{"line_id":"L1","sku":"","description":"Test plate","quantity":24,"uom":"nos","unit_rate":100,"gst_pct":18}]'::jsonb);
 q=public.ig_vendor_portal(jsonb_build_object('action','quote','id',ass->>'id','version',ass->'version','data',d));
 perform pg_temp.ok(q->>'status'='submitted' and exists(select 1 from public.ig_operations where id=(q->>'id')::uuid and data->>'vendor_id'=v->>'id'),'Supplier quotation reaches comparison register');
 perform pg_temp.reject(jsonb_build_object('action','quote','id',ass->>'id','version',ass->'version','data',d),true,'Stale supplier submission cannot overwrite');
 update public.ig_vendor_contacts set active=false where vendor_id=(v->>'id')::uuid;
 perform pg_temp.ok(jsonb_array_length(public.ig_vendor_portal('{"action":"dashboard"}'))=0,'Revoked supplier loses RFQ access');
 update public.ig_profiles set roles=original_roles,practice_grants=original_grants where id=uid;perform set_config('request.jwt.claims',claims::text,true);
 d=d||jsonb_build_object('freight',100,'discount',20,'total_paise',1);
 r=public.ig_procurement(jsonb_build_object('action','quote','id',r->>'id','version',r->'version','reviewed',true,'quotation',d));
 perform pg_temp.ok((r->'quotation'->>'total_paise')::bigint=291200,'Customer total is calculated server-side and ignores supplied total');
 perform pg_temp.ok(not (r->'quotation') ? 'vendor_id','Customer quotation contains no supplier identity');
 update public.ig_profiles set roles=array['client'],practice_grants='{}' where id=uid;perform set_config('request.jwt.claims',(claims||'{"aal":"aal1"}')::text,true);
 perform pg_temp.reject(jsonb_build_object('action','accept','id',r->>'id','version',r->'version','quote_version',0,'accepted',true),false,'Customer must accept exact quote revision');
 r=public.ig_procurement(jsonb_build_object('action','accept','id',r->>'id','version',r->'version','quote_version',r->'quote_version','accepted',true));
 perform pg_temp.ok(r->>'status'='accepted' and r->>'accepted_at' is not null,'Quote acceptance records identity, revision, time and policy');
 perform pg_temp.reject(jsonb_build_object('action','cancel','id',r->>'id','version',r->'version'),false,'Accepted commitments cannot be silently cancelled');
 update public.ig_profiles set roles=original_roles,practice_grants=original_grants where id=uid;perform set_config('request.jwt.claims',claims::text,true);
 r=public.ig_procurement(jsonb_build_object('action','invoice','id',r->>'id','version',r->'version'));
 perform pg_temp.ok(exists(select 1 from public.ig_payment_requests where id=(r->>'payment_request_id')::uuid and user_id=uid and amount_paise=291200),'Payment request uses accepted total and correct customer');
 perform pg_temp.reject(jsonb_build_object('action','invoice','id',r->>'id','version',r->'version'),false,'Duplicate payment request is rejected');
 perform pg_temp.reject(jsonb_build_object('action','quote','id',r->>'id','version',r->'version','reviewed',true,'quotation',d),false,'Accepted commercial quote is immutable');
 perform pg_temp.ok(not has_table_privilege('anon','public.ig_procurement_requests','select') and not has_table_privilege('authenticated','public.ig_vendor_assignments','insert'),'Direct anonymous reads and unauthorised assignment writes denied');
end$$;
select * from checks;
rollback;
